import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        static final int MAX_N = 1 << 21;
        static final double[] cs = new double[MAX_N];
        static final double[] sn = new double[MAX_N];
        static final double[] csi = new double[MAX_N];
        static final double[] sni = new double[MAX_N];

        static {
            for (int len = 1; len <= MAX_N; len <<= 1) {
                for (int i = len / 2; i < len; i++) {
                    double angle = 2 * Math.PI * (i - len / 2) / len;
                    cs[i] = Math.cos(angle);
                    sn[i] = Math.sin(angle);
                    csi[i] = Math.cos(-angle);
                    sni[i] = Math.sin(-angle);
                }
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            final int MOD = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                v[in.nextInt()] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if ((p & 1) == 1) {
                    ans = multiplyPolynomial(ans, v, MOD);
                }
                p >>= 1;
                if (p == 0) break;
                v = multiplyPolynomial(v, v, MOD);
            }
            long result = 0;
            for (int val : ans) {
                result = (result + (long) val * val) % MOD;
            }
            out.println(result);
        }

        int[] multiplyPolynomial(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

            double[] aReal = new double[n];
            double[] aImag = new double[n];
            for (int i = 0; i < a.length; i++) {
                int x = ((a[i] % mod) + mod) % mod;
                aReal[i] = x & 0x7FFF;
                aImag[i] = x >>> 15;
            }
            performFFT(aReal, aImag, false);

            double[] bReal = new double[n];
            double[] bImag = new double[n];
            for (int i = 0; i < b.length; i++) {
                int x = ((b[i] % mod) + mod) % mod;
                bReal[i] = x & 0x7FFF;
                bImag[i] = x >>> 15;
            }
            performFFT(bReal, bImag, false);

            double[] resReal1 = new double[n];
            double[] resImag1 = new double[n];
            double[] resReal2 = new double[n];
            double[] resImag2 = new double[n];

            for (int i = 0; i < n; i++) {
                int j = (n - i) & (n - 1);

                double a1r = (aReal[i] + aReal[j]) * 0.5;
                double a1i = (aImag[i] - aImag[j]) * 0.5;
                double a2r = (aImag[i] + aImag[j]) * 0.5;
                double a2i = (aReal[j] - aReal[i]) * 0.5;

                double b1r = (bReal[i] + bReal[j]) * 0.5;
                double b1i = (bImag[i] - bImag[j]) * 0.5;
                double b2r = (bImag[i] + bImag[j]) * 0.5;
                double b2i = (bReal[j] - bReal[i]) * 0.5;

                resReal1[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
                resImag1[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
                resReal2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
                resImag2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
            }

            performFFT(resReal1, resImag1, true);
            performFFT(resReal2, resImag2, true);

            int[] result = new int[need];
            for (int i = 0; i < need; i++) {
                long aa = Math.round(resReal1[i]);
                long bb = Math.round(resReal2[i]);
                long cc = Math.round(resImag1[i]);
                result[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
            }
            return result;
        }

        void performFFT(double[] real, double[] imag, boolean inverse) {
            int n = real.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    double tmp = real[i];
                    real[i] = real[j];
                    real[j] = tmp;
                    tmp = imag[i];
                    imag[i] = imag[j];
                    imag[j] = tmp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                int step = cs.length / len;
                for (int i = 0; i < n; i += len) {
                    for (int j = 0, idx = 0; j < half; j++, idx += step) {
                        double wReal = inverse ? csi[half + j] : cs[half + j];
                        double wImag = inverse ? sni[half + j] : sn[half + j];

                        double uR = real[i + j];
                        double uI = imag[i + j];
                        double vR = real[i + j + half] * wReal - imag[i + j + half] * wImag;
                        double vI = real[i + j + half] * wImag + imag[i + j + half] * wReal;

                        real[i + j] = uR + vR;
                        imag[i + j] = uI + vI;
                        real[i + j + half] = uR - vR;
                        imag[i + j + half] = uI - vI;
                    }
                }
            }

            if (inverse) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    real[i] *= invN;
                    imag[i] *= invN;
                }
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                val = val * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return val * sign;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
